// What an OUI vendor string may look like → which mark to draw. First match wins.
const rules: [RegExp, string][] = [
  [/fortinet|fortigate/, "fortinet"],
  [/\bavm\b|fritz/, "avm"],
  [/cisco|meraki|linksys/, "cisco"],
  [/ubiquiti|unifi/, "ubiquiti"],
  [/mikrotik|routerboard/, "mikrotik"],
  [/tp-?link|tplink/, "tplink"],
  [/netgear/, "netgear"],
  [/synology/, "synology"],
  [/qnap/, "qnap"],
  [/proxmox/, "proxmox"],
  [/vmware/, "vmware"],
  [/sonicwall/, "sonicwall"],
  [/palo ?alto/, "paloaltonetworks"],
  [/huawei/, "huawei"],
  [/zebra/, "zebratechnologies"],
  [/apple/, "apple"],
  [/hewlett|hp inc|\bhpe?\b/, "hp"],
  [/\bdell\b/, "dell"],
  [/lenovo|thinkpad/, "lenovo"],
  [/asus(tek)?/, "asus"],
  [/supermicro|super micro/, "supermicro"],
  [/intel/, "intel"],
  [/nvidia/, "nvidia"],
  [/samsung/, "samsung"],
  [/epson|seiko epson/, "epson"],
  [/kyocera/, "kyocera"],
  [/seagate/, "seagate"],
  [/raspberry/, "raspberrypi"],
  [/sonos/, "sonos"],
  [/philips|signify/, "philipshue"],
  [/siemens/, "siemens"],
  [/home ?assistant|nabu casa/, "homeassistant"],
  [/canonical|ubuntu/, "ubuntu"],
  [/debian/, "debian"],
]

/** The mark for a vendor string, or null when we do not know the brand. */
export function vendorIcon(vendor: string | undefined): Icon | null {
  if (!vendor) return null
  const v = vendor.toLowerCase()
  for (const [re, slug] of rules) if (re.test(v)) return icons[slug] ?? null
  return null
}

// A pure black or very dark mark disappears on the console's ground: those are
// drawn in the foreground colour instead of the brand colour.
function drawColour(hex: string) {
  const n = parseInt(hex.slice(1), 16)
  const lum = (0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255)) / 255
  return lum < 0.28 ? "currentColor" : hex
}

/** Draws the vendor's mark; renders nothing when the brand is unknown. */
export function VendorMark({ vendor, className = "size-4" }: { vendor?: string; className?: string }) {
  const i = vendorIcon(vendor)
  if (!i) return null
  return (
    <svg viewBox="0 0 24 24" className={className} role="img" aria-label={i.t}>
      <title>{i.t}</title>
      <path d={i.d} fill={drawColour(i.c)} />
    </svg>
  )
}
